package android.app; import java.util.*; public class NotificationManager {public Notification last;public static final int IMPORTANCE_HIGH=4,IMPORTANCE_NONE=0;public boolean enabled=true,fail=false;public int posts=0;public Map<String,NotificationChannel> channels=new HashMap<>();public void createNotificationChannel(NotificationChannel c){channels.putIfAbsent(c.id,c);}public boolean areNotificationsEnabled(){return enabled;}public NotificationChannel getNotificationChannel(String id){return channels.get(id);}public void notify(int id,Notification n){if(fail)throw new SecurityException();last=n;posts++;}}
